import itertools
import json

names = ("Kim", "Mahr", "Parra", "Quinn", "Stuckey", "Tiao", "Udall")
models = []

for zones in itertools.product((1, 2, 3), repeat=len(names)):
    z = dict(zip(names, zones))
    if (z["Parra"] == 1) == (z["Tiao"] == 1):
        continue
    if (z["Tiao"] == 2) == (z["Udall"] == 2):
        continue
    if z["Parra"] != z["Quinn"]:
        continue
    if z["Stuckey"] != z["Udall"]:
        continue
    if zones.count(3) <= zones.count(2):
        continue
    if z["Mahr"] != z["Stuckey"]:
        continue
    models.append(z)

options = {
    "A": lambda z: z["Kim"] == 2,
    "B": lambda z: z["Mahr"] == 1,
    "C": lambda z: z["Parra"] == 3,
    "D": lambda z: z["Stuckey"] == 2,
    "E": lambda z: z["Tiao"] == 1,
}
matches = {
    letter: [z for z in models if test(z)]
    for letter, test in options.items()
}
possible = [letter for letter, witnesses in matches.items() if witnesses]

if len(possible) != 1:
    print("UNSUPPORTED")
else:
    answer = possible[0]
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "valid_assignments": len(models),
            "option_counts": {k: len(v) for k, v in matches.items()},
            "witness": matches[answer][0]
        }
    }, separators=(",", ":")))
